  textTransform?: "none" | "uppercase" | "lowercase" | "capitalize"; smallCaps?: boolean;
  numerals?: "normal" | "lining" | "oldstyle"; numeralWidth?: "normal" | "tabular" | "proportional"; slashedZero?: boolean;
